CREATE TABLE IF NOT EXISTS chart_of_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES tenants(id),code text NOT NULL,name text NOT NULL,account_type text NOT NULL CHECK(account_type IN('asset','liability','equity','income','expense')),is_active boolean NOT NULL DEFAULT true,UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS journal_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES tenants(id),entry_date date NOT NULL DEFAULT current_date,reference_type text,reference_id uuid,description text,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),journal_id uuid NOT NULL REFERENCES journal_entries(id) ON DELETE CASCADE,account_id uuid NOT NULL REFERENCES chart_of_accounts(id),debit numeric(14,2) NOT NULL DEFAULT 0,credit numeric(14,2) NOT NULL DEFAULT 0,CHECK((debit=0)<>(credit=0)));
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES tenants(id),user_id uuid REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid,old_data jsonb,new_data jsonb,ip_address inet,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES tenants(id),entity_type text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),synced_at timestamptz);
INSERT INTO chart_of_accounts(tenant_id,code,name,account_type) SELECT id,'1000','Cash','asset' FROM tenants ON CONFLICT DO NOTHING;
INSERT INTO chart_of_accounts(tenant_id,code,name,account_type) SELECT id,'1100','Accounts Receivable','asset' FROM tenants ON CONFLICT DO NOTHING;
INSERT INTO chart_of_accounts(tenant_id,code,name,account_type) SELECT id,'2000','Accounts Payable','liability' FROM tenants ON CONFLICT DO NOTHING;
INSERT INTO chart_of_accounts(tenant_id,code,name,account_type) SELECT id,'4000','Sales Revenue','income' FROM tenants ON CONFLICT DO NOTHING;
INSERT INTO chart_of_accounts(tenant_id,code,name,account_type) SELECT id,'5000','Cost of Goods Sold','expense' FROM tenants ON CONFLICT DO NOTHING;
